keywords = ["PR 842", "842cafe", "840bead", "record-54bad5e8e1", "record-7b1da28762", "record-a2d078a170", "record-fa1b95eae5", "record-b5a8ddac8f", "record-802a8b0629", "record-4f1efc746f"]

matches = {}
for root, dirs, files in os.walk("/workspace/product"):
    for file in files:
        path = os.path.join(root, file)
        try:
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()
                for kw in keywords:
                    if kw in content:
                        if path not in matches:
                            matches[path] = []
                        matches[path].append(kw)
        except Exception:
            pass

for p, kws in sorted(matches.items()):
    print(f"{p}: {kws}")
'
